const CACHE='sojang-shell-v1';
const ASSETS=['./','./index.html','./style.css','./app.js','./icon.svg','./icon-192.png','./icon-512.png','./manifest.webmanifest','./sample.wav'];
self.addEventListener('install',event=>event.waitUntil((async()=>{const cache=await caches.open(CACHE);for(const path of ASSETS){const response=await fetch(path,{credentials:'same-origin'});if(!response.ok||response.redirected)throw new Error('App cache unavailable');if(path==='./'||path==='./index.html'){const body=await response.clone().text();if(!body.includes('sojang-music')&&!body.includes('나만의 음악'))throw new Error('App shell unavailable')}await cache.put(path,response)}await self.skipWaiting()})()));
self.addEventListener('activate',event=>event.waitUntil((async()=>{await Promise.all((await caches.keys()).filter(k=>k.startsWith('sojang-shell-')&&k!==CACHE).map(k=>caches.delete(k)));await self.clients.claim()})()));
self.addEventListener('fetch',event=>{const u=new URL(event.request.url);if(event.request.method!=='GET'||u.origin!==self.location.origin)return;const allowed=ASSETS.some(path=>new URL(path,self.registration.scope).pathname===u.pathname);if(!allowed&&event.request.mode!=='navigate')return;event.respondWith((async()=>{const cache=await caches.open(CACHE);if(event.request.mode==='navigate'){try{const response=await fetch(event.request);if(response.ok&&!response.redirected&&(await response.clone().text()).includes('나만의 음악'))await cache.put('./',response.clone());return response}catch{return (await cache.match('./'))||Response.error()}}return (await cache.match(event.request))||fetch(event.request)})())});
